import{s as t,a as m}from"./api-vtkRPzLV.js";document.getElementById("btn-submit").addEventListener("click",async()=>{const n=document.getElementById("f-name").value.trim(),s=document.getElementById("f-phone").value.trim().replace(/\D/g,""),r=document.getElementById("f-addr").value.trim(),a=document.getElementById("f-bno").value.trim(),d=document.getElementById("f-cat").value;if(!n)return t("상점명을 입력해 주세요.","error");if(!/^01[0-9]{8,9}$/.test(s))return t("올바른 휴대폰 번호를 입력해 주세요.","error");if(!r)return t("주소를 입력해 주세요.","error");const e=document.getElementById("btn-submit");e.disabled=!0,e.innerHTML='<span class="spinner"></span> 신청 중...';try{await m.post("/merchant/apply",{name:n,phone:s,businessNo:a,address:r,category:d}),document.getElementById("form-view").classList.add("hidden"),document.getElementById("success-view").classList.remove("hidden")}catch(o){t(o.message,"error"),e.disabled=!1,e.textContent="입점 신청하기"}});
